 "content": "def transform(grid):
    # Infer the reference sequence from the complete contiguous object at bottom.
    # Place that sequence, starting with its matching numbered color, at each
    # isolated colored marker, preserving grid dimensions.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    full = next((row[:] for row in g if sum(v != 0 for v in row) > 1), None)
    if full is None:
        return g
    seq = [v for v in full if v != 0]
    # In examples the sequence is shown as one contiguous run; retain its order.
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color and (r != next((rr for rr in range(h) if sum(v != 0 for v in g[rr]) > 1), -1)):
                # A marker triggers the pattern at its own location, aligned so
                # that the marker color is first when it occurs in the sequence.
                if color in seq:
                    i = seq.index(color)
                    for k, v in enumerate(seq[i:] + seq[:i]):
                        if c + k < w:
                            g[r][c+k] = v
    return g
