            if row[c] == 0:
                c += 1
                continue
            start = c
            vals = []
            while c < w and row[c] != 0:
                vals.append(row[c])
                c += 1
            if len(vals) > 1:
                templates.append(vals)
                template_rows.add(r)

    for r, row in enumerate(grid):
        if r in template_rows:
            continue
